def transform(grid):
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    # two four-color runs supplied along the bottom row
    bottom=grid[-1]
    nz=[(i,v) for i,v in enumerate(bottom) if v]
    seq=[v for i,v in nz]
    # runs are the first and second groups of four
    groups=[seq[i:i+4] for i in range(0,len(seq),4)]
    for r in range(h-1):
        for c,v in enumerate(grid[r]):
            if v==0: continue
            for group in groups:
                if v in group:
                    start=c-group.index(v)
                    for j,x in enumerate(group):
                        k=start+j
                        if 0<=k<w: g[r][k]=x
                    break
    return g
